              : !coverageComplete ? 'incomplete-critic-coverage'
                : 'not-converged',
}
if (finalValidationEligible) {
  const finalResult = await agent(
    'Read-only final validator. This target-aware review reached a complete convergence candidate. Discover canonical repository validation from project docs, scripts, and CI. ' +
    'Run the FULL test suite once plus canonical full build/typecheck needed for certification. Avoid redundant variants. Return unavailable if complete validation cannot run.\n\n' +
    JSON.stringify({ parsedTarget, targetPlan, manifestVersion, manifestFiles, manifestChanges, fixLog }),
    { tier: 'medium', label: 'final validation', schema: finalValidationSchema, retries: 0, timeoutMs: POLICY.finalValidationTimeoutMs })
  finalValidation = finalResult || { status: 'unavailable', commands: [], summary: 'Final validation returned no result.', failures: ['Missing final validation coverage.'], reason: 'validator-null' }
}

const verdict = fixerFailure
  ? 'INCONCLUSIVE - fixer failed or timed out; inspect partial working-tree changes'
  : outOfPolicyChanges.length
    ? 'INCONCLUSIVE - fixer changed files outside the target mutation policy'
    : coverageLimitExceeded
      ? 'INCONCLUSIVE - target exceeds coverage limit'
      : !discovery.complete
        ? 'INCONCLUSIVE - target discovery is incomplete'
        : manifestRefreshIncomplete
          ? 'INCONCLUSIVE - post-fix manifest refresh is incomplete'
          : pendingVerificationOverflow.length
            ? 'INCONCLUSIVE - unresolved verification overflow (' + pendingVerificationOverflow.length + ' claim(s))'
            : lastSurvivors.length > 0 && roundsRun >= POLICY.maxRounds
              ? 'STOPPED AT CAP - escalate unresolved blocking findings to a human'
              : lastSurvivors.length === 0 && disputedUnique.length > 0
                ? 'CONVERGED WITH DISPUTED FINDINGS - ' + disputedUnique.length + ' need human review'
                : lastSurvivors.length === 0 && unverifiedUnique.length > 0
                  ? 'CONVERGED WITH UNVERIFIED FINDINGS - ' + unverifiedUnique.length + ' need human review'
                  : lastSurvivors.length === 0 && !converged
                    ? 'STOPPED AT CAP - did not reach ' + POLICY.consecutiveDryRounds + ' consecutive dry rounds on the current manifest'
                    : lastSurvivors.length === 0 && !coverageComplete
                      ? 'INCONCLUSIVE - incomplete critic coverage'
                      : lastSurvivors.length === 0 && unconfirmedFixes.length
                        ? 'CONVERGED WITH UNCONFIRMED FOCUSED VALIDATION - ' + unconfirmedFixes.length + ' fix round(s) need review'
                        : manifestChangedAfterFinalCoveredRound
                          ? 'INCONCLUSIVE - manifest changed after the final covered round'
                          : finalValidation.status === 'failed'
                            ? 'CONVERGED BUT FINAL FULL VALIDATION FAILED'
                            : finalValidation.status !== 'passed'
                              ? 'CONVERGED BUT FINAL FULL VALIDATION UNAVAILABLE'
                              : 'CONVERGED CLEAN'
const efficiency = {
  criticLaneCalls: chunkCoverage.reduce((total, entry) => total + entry.totalLanes, 0),
  verificationClaims,
  verificationVotesRequested: verificationClaims * POLICY.reviewers,
  verificationOverflowClaims: verificationOverflow.length,
  unresolvedVerificationOverflowClaims: pendingVerificationOverflow.length,
  duplicateVerificationClaimsSkipped: verificationDedupSavings,
  focusedValidationRounds: fixLog.length,
  focusedValidationCommands: fixLog.reduce((total, entry) => total + ((entry.focusedValidation && entry.focusedValidation.commands || []).filter((command) => command.status !== 'not_run').length), 0),
  finalFullValidationRuns: finalValidationEligible ? 1 : 0,
}

phase('Report')
const report = await agent(
  'Write an evidence-rich, scannable TARGET-AWARE review report with these sections: verdict/confidence; parsed target and review basis; complete manifest or counts; discovery evidence, exclusions, completeness, warnings and disagreements; manifest changes by round; chunk/file/lane coverage and skipped coverage; model-tier routing; round findings/verification/fixes/changed files/focused validation; final full validation; escalations and lower-severity/external tracked findings; residual risk. ' +
  'Use honest wording. Never claim CONVERGED CLEAN for an empty target, incomplete discovery, skipped files, exceeded bounds, missing/zero critic lanes, a manifest changed after final coverage, fixer failure, verification overflow, disputed/unverified blockers, unconfirmed fixes, out-of-policy changes, or incomplete final validation.\n\n' +
  JSON.stringify({ verdict, parsedTarget, targetPlan, discovery, manifestVersion, manifestFiles, manifestChanges, chunkCoverage, skippedCoverage: chunkState.skippedCoverage,
    oversizedFiles: chunkState.oversizedFiles, routing, limits, trajectory, fixLog, finalValidation, totalAddressed, totalResolved,
    verificationOverflow, pendingVerificationOverflow, unresolved: lastSurvivors, unverified: unverifiedUnique, disputed: disputedUnique,
    outOfPolicyChanges, tracked: trackedUnique, coverageComplete, converged, manifestChangedAfterFinalCoveredRound, residualRisk, efficiency }),
  { tier: 'medium', label: 'synthesis' })

return {
  verdict,
  terminationReason,
  parsedTarget,
  targetPlan,
  targetManifest: { version: manifestVersion, files: manifestFiles, fileCount: manifestFiles.length, totalLines: sumLines(manifestFiles) },
  discovery,
  manifestChanges,
  roundsRun,
  chunks: chunkState.chunks.length,
  chunkSummary: summarizeChunks(chunkState),
  chunkCoverage,
  skippedCoverage: chunkState.skippedCoverage,
  oversizedFiles: chunkState.oversizedFiles,
  limits,
  routing,
  totalAddressed,
  totalResolved,
  totalFixed: totalResolved,
  unresolved: lastSurvivors,
  unverified: unverifiedUnique,
  disputed: disputedUnique,
  tracked: trackedUnique,
  verificationOverflow,
  verificationOverflowCount: verificationOverflow.length,
  unresolvedVerificationOverflow: pendingVerificationOverflow,
  unresolvedVerificationOverflowCount: pendingVerificationOverflow.length,
  outOfPolicyChanges,
  fixerFailure,
  trajectory,
  fixLog,
  finalValidation,
  coverageComplete,
  manifestChangedAfterFinalCoveredRound,
  residualRisk,
  efficiency,
  report,
}
